const clamp = (v, min, max) => (v < min ? min : v > max ? max : v);
const lerp = (a, b, t) => a + (b - a) * t;
const easeOutCubic = (t) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
const easeInOutCubic = (t) => {
  const c = clamp(t, 0, 1);
  return c < 0.5 ? 4 * c * c * c : 1 - Math.pow(-2 * c + 2, 3) / 2;
};

function cubicPoint(p0, c1, c2, p3, t) {
  const u = 1 - t;
  return u * u * u * p0 + 3 * u * u * t * c1 + 3 * u * t * t * c2 + t * t * t * p3;
}

/* ------------------------------------------------------------------ */
/* WebGL2 Capability Check (matching src/mascot3d.js)                 */
/* ------------------------------------------------------------------ */

export function hasWebGL2() {
  try {
    const probe = document.createElement("canvas");
    return Boolean(window.WebGL2RenderingContext && probe.getContext("webgl2"));
  } catch {
    return false;
  }
}

/* ------------------------------------------------------------------ */
/* Textures & Shared Studio Softbox Environment Map                   */
/* ------------------------------------------------------------------ */

function radialTexture(stops, size = 128) {
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const ctx = c.getContext("2d");
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  for (const [offset, color] of stops) g.addColorStop(offset, color);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const sharedGlowTex = radialTexture([
  [0, "rgba(255,255,255,1)"],
  [0.3, "rgba(255,230,200,0.7)"],
  [0.65, "rgba(224,166,120,0.18)"],
  [1, "rgba(0,0,0,0)"],
]);

/**
 * Creates the exact studio softbox environment map used by the hero mascot.
 * Gives the robots their signature glossy reflections and physical depth.
 */
export function createStudioEnvMap(renderer) {
  const envScene = new THREE.Scene();
  envScene.background = new THREE.Color("#030303");

  function softbox(w, h, x, y, z, color, intensity) {
    const m = new THREE.Mesh(
      new THREE.SphereGeometry(0.5, 32, 16),
      new THREE.MeshBasicMaterial({ color: new THREE.Color(color).multiplyScalar(intensity) })
    );
    m.scale.set(w, h, 0.3);
    m.position.set(x, y, z);
    m.lookAt(0, 0, 0);
    envScene.add(m);
  }

  softbox(5, 3.2, -3, 4.5, 4, 0xffffff, 3.2);
  softbox(1.2, 6, 6, 0.5, 2, 0xffffff, 1.2);
  softbox(3, 1, 1.5, 5, -1, 0xffffff, 0.9);
  softbox(4, 5, -5, 0, -4, 0xe0a678, 1.3);
  softbox(4, 5, 5, 0, -4, 0xa9c9b6, 0.85);
  softbox(6, 3, 0, -5, 1, 0xc98b5e, 0.4);
  softbox(5, 3, 0, -3.5, 3, 0xffffff, 1.1);

  const pmrem = new THREE.PMREMGenerator(renderer);
  const tex = pmrem.fromScene(envScene, 0.02).texture;
  pmrem.dispose();
  return tex;
}

/* ------------------------------------------------------------------ */
/* Fresnel Rim Shader (from src/mascot3d.js)                           */
/* ------------------------------------------------------------------ */

function rimMaterial(color, power = 3.0, strength = 1.45) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uColor: { value: new THREE.Color(color) },
      uPower: { value: power },
      uStrength: { value: strength },
    },
    vertexShader: `
      varying vec3 vN;
      varying vec3 vV;
      void main() {
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        vN = normalize(normalMatrix * normal);
        vV = normalize(-mv.xyz);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      uniform vec3 uColor;
      uniform float uPower;
      uniform float uStrength;
      varying vec3 vN;
      varying vec3 vV;
      void main() {
        vec3 N = normalize(vN);
        vec3 V = normalize(vV);
        float f = pow(1.0 - max(dot(N, V), 0.0), uPower);
        gl_FragColor = vec4(uColor * f * uStrength, f);
      }
    `,
    blending: THREE.AdditiveBlending,
    transparent: true,
    depthWrite: false,
  });
}

function addRimShell(mesh, color, power, strength) {
  const shell = new THREE.Mesh(mesh.geometry, rimMaterial(color, power, strength));
  shell.renderOrder = 2;
  mesh.add(shell);
  return shell;
}

/* ------------------------------------------------------------------ */
/* Visor Geometry Fitting (from src/mascot3d.js)                       */
/* ------------------------------------------------------------------ */

function roundedRectShape(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2;
  const y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(-x - r, y);
  s.quadraticCurveTo(-x, y, -x, y + r);
  s.lineTo(-x, -y - r);
  s.quadraticCurveTo(-x, -y, -x - r, -y);
  s.lineTo(x + r, -y);
  s.quadraticCurveTo(x, -y, x, -y - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

function subdivide4(geo) {
  const pos = geo.attributes.position;
  const verts = [];
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const c = new THREE.Vector3();
  for (let i = 0; i < pos.count; i += 3) {
    a.fromBufferAttribute(pos, i);
    b.fromBufferAttribute(pos, i + 1);
    c.fromBufferAttribute(pos, i + 2);
    const ab = a.clone().add(b).multiplyScalar(0.5);
    const bc = b.clone().add(c).multiplyScalar(0.5);
    const ca = c.clone().add(a).multiplyScalar(0.5);
    verts.push(
      a.x, a.y, a.z, ab.x, ab.y, ab.z, ca.x, ca.y, ca.z,
      ab.x, ab.y, ab.z, b.x, b.y, b.z, bc.x, bc.y, bc.z,
      ca.x, ca.y, ca.z, bc.x, bc.y, bc.z, c.x, c.y, c.z,
      ab.x, ab.y, ab.z, bc.x, bc.y, bc.z, ca.x, ca.y, ca.z
    );
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
  return g;
}

function visorGeometry(w, h, corner, centerY, radius) {
  let g = new THREE.ShapeGeometry(roundedRectShape(w, h, corner), 36).toNonIndexed();
  for (let i = 0; i < 2; i++) g = subdivide4(g);
  const p = g.attributes.position;
  const normals = new Float32Array(p.count * 3);
  const v = new THREE.Vector3();
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const y = p.getY(i) + centerY;
    const z = Math.sqrt(Math.max(radius * radius - x * x - y * y, 0));
    p.setXYZ(i, x, y, z);
    v.set(x, y, z).normalize();
    normals[i * 3] = v.x;
    normals[i * 3 + 1] = v.y;
    normals[i * 3 + 2] = v.z;
  }
  g.setAttribute("normal", new THREE.BufferAttribute(normals, 3));
  g.computeBoundingSphere();
  return g;
}

/* ------------------------------------------------------------------ */
/* 3D Visor Eye Expressions                                            */
/* ------------------------------------------------------------------ */

function buildEyeNodes3D(bot, R) {
  const accent = bot.accent;
  const soft = bot.accentSoft || accent;
  const face = bot.face || "iris";

  const eyeTex = radialTexture([
    [0, "#ffffff"],
    [0.4, soft],
    [0.75, accent],
    [1, "#0a0806"],
  ]);

  const eyeMat = (extra) =>
    new THREE.MeshBasicMaterial(
      Object.assign({ transparent: true, toneMapped: false, depthWrite: false, depthTest: false }, extra)
    );

  const eyes = [];

  const addEyeMount = (side) => {
    const x = 0.43 * side;
    const y = -0.07;
    const r = R * 1.045;
    const z = Math.sqrt(Math.max(r * r - x * x - y * y, 0));
    const g = new THREE.Group();
    g.position.set(x, y, z);
    g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), g.position.clone().normalize());

    /* Subtle additive eye glow halo behind each eye inside visor */
    const halo = new THREE.Mesh(
      new THREE.CircleGeometry(0.38, 32),
      eyeMat({ map: sharedGlowTex, color: new THREE.Color(accent), opacity: 0.55, blending: THREE.AdditiveBlending })
    );
    halo.position.z = -0.003;
    halo.renderOrder = 8;
    g.add(halo);

    const pupilWrap = new THREE.Group();
    g.add(pupilWrap);

    switch (face) {
      case "happy": {
        /* Glowing happy curve arch (^ _ ^) */
        const arch = new THREE.Mesh(
          new THREE.RingGeometry(0.12, 0.18, 32, 1, 0, Math.PI),
          eyeMat({ color: new THREE.Color(soft), side: THREE.DoubleSide })
        );
        arch.renderOrder = 10;
        pupilWrap.add(arch);
        break;
      }

      case "focused": {
        /* Angled focused brow */
        const brow = new THREE.Mesh(
          new THREE.PlaneGeometry(0.32, 0.1),
          eyeMat({ color: new THREE.Color(soft) })
        );
        brow.rotation.z = side * 0.22;
        brow.renderOrder = 10;
        const pup = new THREE.Mesh(
          new THREE.CircleGeometry(0.065, 16),
          eyeMat({ color: new THREE.Color("#0a0806") })
        );
        pup.position.set(0, -0.02, 0.002);
        pup.renderOrder = 11;
        pupilWrap.add(brow, pup);
        break;
      }

      case "wink": {
        if (side < 0) {
          /* Open iris eye on left */
          const iris = new THREE.Mesh(new THREE.CircleGeometry(0.165, 32), eyeMat({ map: eyeTex }));
          iris.renderOrder = 10;
          const pupil = new THREE.Mesh(new THREE.CircleGeometry(0.078, 24), eyeMat({ color: 0x0a0806 }));
          pupil.position.z = 0.002;
          pupil.renderOrder = 11;
          const glint = new THREE.Mesh(new THREE.CircleGeometry(0.024, 16), eyeMat({ color: 0xffffff }));
          glint.position.set(0.034, 0.035, 0.004);
          glint.renderOrder = 12;
          pupilWrap.add(iris, pupil, glint);
        } else {
          /* Wink arch on right */
          const arch = new THREE.Mesh(
            new THREE.RingGeometry(0.12, 0.18, 32, 1, 0, Math.PI),
            eyeMat({ color: new THREE.Color(soft), side: THREE.DoubleSide })
          );
          arch.renderOrder = 10;
          pupilWrap.add(arch);
        }
        break;
      }

      case "pixel": {
        /* Dual glowing LED rounded rects */
        const rect = new THREE.Mesh(
          new THREE.PlaneGeometry(0.18, 0.28),
          eyeMat({ color: new THREE.Color(soft) })
        );
        rect.renderOrder = 10;
        const pip = new THREE.Mesh(
          new THREE.CircleGeometry(0.026, 12),
          eyeMat({ color: 0xffffff })
        );
        pip.position.set(0.025, 0.04, 0.002);
        pip.renderOrder = 11;
        pupilWrap.add(rect, pip);
        break;
      }

      case "spark": {
        /* 4-point star sparkle eye */
        const starGeo = new THREE.BufferGeometry();
        const pts = [
          0, 0.16, 0,   0.04, 0.04, 0,  0.16, 0, 0,
          0.16, 0, 0,   0.04, -0.04, 0, 0, -0.16, 0,
          0, -0.16, 0,  -0.04, -0.04, 0, -0.16, 0, 0,
          -0.16, 0, 0,  -0.04, 0.04, 0,  0, 0.16, 0,
        ];
        starGeo.setAttribute("position", new THREE.Float32BufferAttribute(pts, 3));
        const star = new THREE.Mesh(starGeo, eyeMat({ color: new THREE.Color(soft), side: THREE.DoubleSide }));
        star.renderOrder = 10;
        const pip = new THREE.Mesh(new THREE.CircleGeometry(0.03, 12), eyeMat({ color: 0xffffff }));
        pip.position.z = 0.003;
        pip.renderOrder = 11;
        pupilWrap.add(star, pip);
        break;
      }

      case "iris":
      default: {
        const ring = new THREE.Mesh(
          new THREE.RingGeometry(0.168, 0.21, 48),
          eyeMat({ color: new THREE.Color(soft) })
        );
        ring.position.z = -0.001;
        ring.renderOrder = 9;
        const iris = new THREE.Mesh(new THREE.CircleGeometry(0.168, 48), eyeMat({ map: eyeTex }));
        iris.renderOrder = 10;
        const pupil = new THREE.Mesh(new THREE.CircleGeometry(0.082, 32), eyeMat({ color: 0x0a0806 }));
        pupil.position.z = 0.002;
        pupil.renderOrder = 11;
        const glint = new THREE.Mesh(new THREE.CircleGeometry(0.025, 16), eyeMat({ color: 0xffffff }));
        glint.position.set(0.035, 0.036, 0.004);
        glint.renderOrder = 12;
        pupilWrap.add(ring, iris, pupil, glint);
        break;
      }
    }

    eyes.push({ group: g, pupilWrap, qSurface: g.quaternion.clone() });
    return g;
  };

  const eyeL = addEyeMount(-1);
  const eyeR = addEyeMount(1);

  return { eyeL, eyeR, eyes };
}

/* ------------------------------------------------------------------ */
/* Build Authentic 3D Robot Rig (matching src/mascot3d.js)             */
/* ------------------------------------------------------------------ */

/**
 * Creates a fully articulated 3D robot model with the exact materials,
 * geometry, studio lighting reflections, black curved visor, floating arms,
 * and antennas from the portfolio's original mascot, retinted with the
 * bot's distinct solid glossy color palette.
 */
export function createBot3DRig(botDef, options = {}) {
  const bot = { ...DEFAULT_BOTS[0], ...botDef };
  const R = 1.0;

  const rootGroup = new THREE.Group();
  const robotGroup = new THREE.Group();
  const bodyGroup = new THREE.Group();
  const headGroup = new THREE.Group();

  bodyGroup.add(headGroup);
  robotGroup.add(bodyGroup);
  rootGroup.add(robotGroup);

  /* 1. Main Spherical Head Shell (Solid Glossy Lacquer / Ceramic) */
  const shellMat = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color(bot.shellColor),
    metalness: 0.04,
    roughness: 0.16,
    clearcoat: 1.0,
    clearcoatRoughness: 0.08,
    envMapIntensity: 2.0,
  });
  const shellMesh = new THREE.Mesh(new THREE.SphereGeometry(R, 64, 32), shellMat);
  headGroup.add(shellMesh);
  addRimShell(shellMesh, bot.accent, 3.0, 1.45);

  /* Luminous Ambient Studio Backing Aura (matching src/mascot3d.js line 241) */
  const haze = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: sharedGlowTex,
      color: new THREE.Color(bot.halo || bot.accent),
      opacity: 0.38,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
      depthWrite: false,
      transparent: true,
    })
  );
  haze.scale.set(3.4, 3.4, 1);
  haze.position.set(0, 0, -1.05);
  robotGroup.add(haze);

  /* 2. Cylindrical Side Ear Pucks */
  const earMat = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color(bot.shellColor),
    metalness: 0.08,
    roughness: 0.22,
    clearcoat: 0.9,
    clearcoatRoughness: 0.12,
    envMapIntensity: 1.8,
  });
  for (const s of [-1, 1]) {
    const ear = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 0.2, 32), earMat);
    ear.rotation.z = Math.PI / 2;
    ear.position.x = s * 1.0;
    headGroup.add(ear);
    addRimShell(ear, bot.accent, 2.8, 1.1);
  }

  /* 3. Antennas + Glowing Tip Spheres */
  const antLColor = bot.antennaL || bot.accent;
  const antRColor = bot.antennaR || bot.accent;
  const antennaGlows = [];

  for (const s of [-1, 1]) {
    const color = s < 0 ? antLColor : antRColor;
    const rod = new THREE.Mesh(
      new THREE.CylinderGeometry(0.035, 0.035, 0.55, 16),
      shellMat
    );
    rod.position.set(s * 0.42, 1.25, 0);
    headGroup.add(rod);

    const ball = new THREE.Mesh(
      new THREE.SphereGeometry(0.105, 24, 16),
      new THREE.MeshPhysicalMaterial({
        color: new THREE.Color(color),
        emissive: new THREE.Color(color),
        emissiveIntensity: 2.8,
        roughness: 0.15,
        clearcoat: 1.0,
        clearcoatRoughness: 0.08,
      })
    );
    ball.position.set(s * 0.42, 1.55, 0);
    headGroup.add(ball);

    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: sharedGlowTex,
        color: new THREE.Color(color),
        opacity: 0.95,
        blending: THREE.AdditiveBlending,
        toneMapped: false,
        depthWrite: false,
        transparent: true,
      })
    );
    glow.scale.set(0.65, 0.65, 1);
    glow.position.copy(ball.position);
    headGroup.add(glow);
    antennaGlows.push(glow);
  }

  /* 4. Glossy Dark Curved Visor */
  const bezel = new THREE.Mesh(
    visorGeometry(1.86, 1.12, 0.46, -0.07, R * 1.03),
    new THREE.MeshPhysicalMaterial({
      color: 0x080706,
      roughness: 0.24,
      metalness: 0.15,
      clearcoat: 0.85,
      polygonOffset: true,
      polygonOffsetFactor: -6,
      polygonOffsetUnits: -6,
    })
  );
  bezel.renderOrder = 3;

  const glass = new THREE.Mesh(
    visorGeometry(1.74, 1.0, 0.4, -0.07, R * 1.036),
    new THREE.MeshPhysicalMaterial({
      color: 0x010101,
      roughness: 0.06,
      metalness: 0,
      clearcoat: 1.0,
      clearcoatRoughness: 0.04,
      envMapIntensity: 1.8,
      polygonOffset: true,
      polygonOffsetFactor: -8,
      polygonOffsetUnits: -8,
    })
  );
  glass.renderOrder = 4;
  headGroup.add(bezel, glass);

  /* 5. Glowing Visor Expression Eyes */
  const { eyeL, eyeR, eyes } = buildEyeNodes3D(bot, R);
  headGroup.add(eyeL, eyeR);

  /* 6. Detached Floating Capsule Arms */
  const armMat = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color(bot.armColor || bot.shellColor),
    metalness: 0.04,
    roughness: 0.22,
    clearcoat: 0.85,
    clearcoatRoughness: 0.12,
    envMapIntensity: 1.6,
  });

  const makeArm = (side) => {
    const wrap = new THREE.Group();
    wrap.position.set(side * 0.92, -0.72, 0.1);
    wrap.rotation.z = side * 0.47;

    const armMesh = new THREE.Mesh(new THREE.CapsuleGeometry(0.22, 0.42, 12, 32), armMat);
    wrap.add(armMesh);
    addRimShell(armMesh, bot.accent, 2.4, 1.25);
    bodyGroup.add(wrap);
    return { wrap, mesh: armMesh, baseZ: side * 0.47 };
  };

  const leftArm = makeArm(-1);
  const rightArm = makeArm(1);

  /* Gaze orientation helper */
  const EYE_BILLBOARD = 0.55;
  const _camLocal = new THREE.Vector3();
  const _eyeDir = new THREE.Vector3();
  const _qBill = new THREE.Quaternion();
  const _Z = new THREE.Vector3(0, 0, 1);

  const orientEyes = (camPos = new THREE.Vector3(0, 0, 5)) => {
    headGroup.updateMatrixWorld(true);
    _camLocal.copy(camPos);
    headGroup.worldToLocal(_camLocal);
    for (const eye of eyes) {
      _eyeDir.copy(_camLocal).sub(eye.group.position).normalize();
      _qBill.setFromUnitVectors(_Z, _eyeDir);
      eye.group.quaternion.copy(eye.qSurface).slerp(_qBill, EYE_BILLBOARD);
    }
  };

  let blinkTimer = 0;
  let isBlinking = false;

  const setGaze = (gx = 0, gy = 0) => {
    const cgx = clamp(gx, -1, 1);
    const cgy = clamp(gy, -1, 1);
    headGroup.rotation.y = cgx * 0.44;
    headGroup.rotation.x = -cgy * 0.32;
    headGroup.rotation.z = -cgx * 0.08;
    for (const eye of eyes) {
      eye.pupilWrap.position.x = cgx * 0.045;
      eye.pupilWrap.position.y = -cgy * 0.035;
    }
  };

  const setMood = (mood = "idle") => {
    if (mood === "working") {
      leftArm.wrap.rotation.z = -0.15;
      rightArm.wrap.rotation.z = 0.15;
      bodyGroup.rotation.y = 0.08;
    } else if (mood === "celebrating") {
      leftArm.wrap.rotation.z = 1.15;
      rightArm.wrap.rotation.z = -1.15;
      headGroup.rotation.x = -0.14;
    } else {
      leftArm.wrap.rotation.z = leftArm.baseZ;
      rightArm.wrap.rotation.z = rightArm.baseZ;
      bodyGroup.rotation.y = 0;
    }
  };

  const blink = (duration = 140) => {
    if (isBlinking) return;
    isBlinking = true;
    for (const eye of eyes) eye.group.scale.y = 0.08;
    window.clearTimeout(blinkTimer);
    blinkTimer = window.setTimeout(() => {
      for (const eye of eyes) eye.group.scale.y = 1.0;
      isBlinking = false;
    }, duration);
  };

  const destroy = () => {
    window.clearTimeout(blinkTimer);
    rootGroup.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose();
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material?.dispose();
      }
    });
  };

  return {
    rootGroup,
    robotGroup,
    bodyGroup,
    headGroup,
    leftArm,
    rightArm,
    antennaGlows,
    eyes,
    bot,
    setGaze,
    setMood,
    blink,
    orientEyes,
    destroy,
  };
}

/* ------------------------------------------------------------------ */
/* Interactive 3D WebGL Bot View (for Roster and standalone chips)     */
/* ------------------------------------------------------------------ */

let _sharedPreviewRenderer = null;
let _sharedPreviewEnvMap = null;

function getSharedPreviewContext() {
  if (!_sharedPreviewRenderer && typeof document !== "undefined") {
    try {
      const offscreen = document.createElement("canvas");
      offscreen.width = 184;
      offscreen.height = 184;
      _sharedPreviewRenderer = new THREE.WebGLRenderer({
        canvas: offscreen,
        alpha: true,
        antialias: true,
        powerPreference: "high-performance",
      });
      _sharedPreviewRenderer.toneMapping = THREE.ACESFilmicToneMapping;
      _sharedPreviewRenderer.toneMappingExposure = 1.0;
      _sharedPreviewRenderer.outputColorSpace = THREE.SRGBColorSpace;
      _sharedPreviewEnvMap = createStudioEnvMap(_sharedPreviewRenderer);
    } catch (e) {
      console.warn("MascotSwarm: shared preview renderer failed", e);
    }
  }
  return { renderer: _sharedPreviewRenderer, envMap: _sharedPreviewEnvMap };
}

/**
 * Creates an interactive 3D WebGL preview of any mascot bot inside
 * the given container element, sharing a single WebGL context to avoid
 * browser context limits while providing live cursor tracking,
 * natural blinking, and mood reactions.
 */
export function createMascot3DView(container, botConfig = {}, opts = {}) {
  const bot = { ...DEFAULT_BOTS[0], ...botConfig };
  const size = opts.size || 88;
  const { renderer, envMap } = getSharedPreviewContext();
  if (!renderer) return null;

  const canvas2D = document.createElement("canvas");
  canvas2D.className = "mswarm-3d-canvas";
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const pxW = Math.round(size * dpr);
  const pxH = Math.round(size * dpr);
  canvas2D.width = pxW;
  canvas2D.height = pxH;
  canvas2D.style.width = `${size}px`;
  canvas2D.style.height = `${size}px`;
  container.appendChild(canvas2D);
  const ctx2D = canvas2D.getContext("2d");

  const scene = new THREE.Scene();
  scene.environment = envMap;
  scene.environmentIntensity = 1.8;

  scene.add(new THREE.HemisphereLight(0xfff8f0, 0x362516, 3.2));
  const keyLight = new THREE.DirectionalLight(0xffffff, 2.4);
  keyLight.position.set(-3, 4, 5);
  scene.add(keyLight);

  const rimLight = new THREE.DirectionalLight(new THREE.Color(bot.accent), 2.2);
  rimLight.position.set(3, -2, -2);
  scene.add(rimLight);

  const fillLight = new THREE.DirectionalLight(0xffffff, 0.9);
  fillLight.position.set(-3, -2, 2);
  scene.add(fillLight);

  const camera = new THREE.PerspectiveCamera(28, 1, 0.1, 100);
  camera.position.set(0, 0, 6.2);
  camera.lookAt(0, 0, 0);

  const rig = createBot3DRig(bot);
  scene.add(rig.rootGroup);

  let rafId = 0;
  let nextBlink = 2.0 + Math.random() * 3.5;
  let elapsed = 0;
  let targetGx = 0;
  let targetGy = 0;
  let curGx = 0;
  let curGy = 0;

  const tick = () => {
    rafId = requestAnimationFrame(tick);
    const dt = 0.016;
    elapsed += dt;

    if (elapsed >= nextBlink) {
      nextBlink = elapsed + 2.4 + Math.random() * 3.8;
      rig.blink();
    }

    curGx += (targetGx - curGx) * 0.12;
    curGy += (targetGy - curGy) * 0.12;
    rig.setGaze(curGx, curGy);
    rig.orientEyes(camera.position);

    /* Gentle breathing bob */
    rig.robotGroup.position.y = Math.sin(elapsed * 2.2) * 0.04;

    /* Render into shared renderer, then copy frame to 2D canvas */
    renderer.setSize(pxW, pxH, false);
    renderer.render(scene, camera);
    ctx2D.clearRect(0, 0, pxW, pxH);
    ctx2D.drawImage(renderer.domElement, 0, 0);
  };

  rafId = requestAnimationFrame(tick);

  const setGaze = (gx, gy) => {
    targetGx = clamp(gx, -1, 1);
    targetGy = clamp(gy, -1, 1);
  };

  const setMood = (mood) => rig.setMood(mood);
  const blink = (d) => rig.blink(d);

  const destroy = () => {
    cancelAnimationFrame(rafId);
    rig.destroy();
    canvas2D.remove();
  };

  return { el: canvas2D, rig, setGaze, setMood, blink, destroy };
}

/* ------------------------------------------------------------------ */
/* Hybrid DOM Bot Element (Compatible API with 3D or crisp SVG)       */
/* ------------------------------------------------------------------ */

export function createMascotBotElement(botConfig = {}, opts = {}) {
  const bot = { ...DEFAULT_BOTS[0], ...botConfig };
  const uid = `msw-${++instanceSeq}`;
  const showPointer = opts.showPointer !== false;
  const showTag = opts.showTag !== false;
  const size = opts.size || 52;

  const root = document.createElement("div");
  root.className = "mswarm-bot";
  root.style.setProperty("--bot-accent", bot.accent);
  root.style.setProperty("--mswarm-bot-size", `${size}px`);
  root.dataset.botId = bot.id || uid;
  root.dataset.face = bot.face || "iris";

  const bodyWrap = document.createElement("div");
  bodyWrap.className = "mswarm-bot__body";

  /* Render 3D WebGL preview view inside bot body if supported */
  const view3D = createMascot3DView(bodyWrap, bot, { size });

  /* Crisp directional pointer arrow at the bot's working corner */
  if (showPointer) {
    const pointerSvg = document.createElementNS(SVG_NS, "svg");
    pointerSvg.setAttribute("class", "mswarm-bot__pointer");
    pointerSvg.setAttribute("viewBox", "0 0 16 16");
    pointerSvg.setAttribute("fill", "none");
    pointerSvg.setAttribute("aria-hidden", "true");
    const pPath = document.createElementNS(SVG_NS, "path");
    pPath.setAttribute("d", "M 2 2 L 13 6.5 L 7.8 8.3 L 6 13.5 Z");
    pPath.setAttribute("fill", bot.accent);
    pPath.setAttribute("stroke", "#000000");
    pPath.setAttribute("stroke-width", "1.6");
    pPath.setAttribute("stroke-linejoin", "round");
    pointerSvg.appendChild(pPath);
    bodyWrap.appendChild(pointerSvg);
  }

  /* Solid Figma-style multiplayer role tag */
  if (showTag && bot.label) {
    const tag = document.createElement("span");
    tag.className = "mswarm-bot__tag";
    const dot = document.createElement("span");
    dot.className = "mswarm-bot__tag-dot";
    const txt = document.createElement("span");
    txt.textContent = bot.label;
    tag.append(dot, txt);
    bodyWrap.appendChild(tag);
  }

  root.appendChild(bodyWrap);

  const setGaze = (gx = 0, gy = 0) => view3D?.setGaze(gx, gy);
  const setMood = (mood = "idle") => {
    root.classList.toggle("is-working", mood === "working");
    root.classList.toggle("is-celebrating", mood === "celebrating");
    view3D?.setMood(mood);
  };
  const blink = (d = 140) => view3D?.blink(d);
  const destroy = () => view3D?.destroy();

  return { el: root, bodyEl: bodyWrap, bot, setGaze, setMood, blink, destroy };
}

/* ------------------------------------------------------------------ */
/* Target Discovery & Blueprint Overlays                              */
/* ------------------------------------------------------------------ */

function inferRole(el) {
  const explicit = el.dataset.mswarmRole;
  if (explicit) return explicit;
  const tag = el.tagName;
  if (tag === "H1" || tag === "H2" || tag === "H3" || tag === "H4") return "heading";
  if (tag === "IMG" || tag === "PICTURE" || tag === "VIDEO" || tag === "CANVAS" || el.classList.contains("screen-frame")) {
    return "media";
  }
  if (
    tag === "BUTTON" ||
    tag === "A" ||
    el.classList.contains("button") ||
    el.classList.contains("chip") ||
    el.getAttribute("role") === "button"
  ) {
    return "control";
  }
  if (tag === "P" || tag === "UL" || tag === "OL" || tag === "DL" || tag === "BLOCKQUOTE") return "text";
  return "box";
}

function discoverTargets(scope, selector) {
  let nodes;
  if (selector) {
    nodes = Array.from(scope.querySelectorAll(selector));
  } else {
    nodes = Array.from(scope.querySelectorAll("[data-swarm]"));
    if (!nodes.length) {
      nodes = Array.from(
        scope.querySelectorAll(
          "article, .card, h1, h2, h3, p, ul, dl, button, a.button, img, picture, figure, [data-mswarm-role]"
        )
      );
    }
  }
  return nodes
    .filter((el) => !el.hasAttribute("data-mswarm-ignore") && !el.closest(".mswarm-layer"))
    .sort((a, b) => {
      const oa = Number(a.dataset.mswarmOrder ?? 0);
      const ob = Number(b.dataset.mswarmOrder ?? 0);
      return oa - ob;
    });
}

function createAgentOverlays(layer, accent) {
  const blueprint = document.createElement("div");
  blueprint.className = "mswarm-blueprint";
  blueprint.style.setProperty("--mswarm-accent", accent);

  const cross = document.createElement("span");
  cross.className = "mswarm-blueprint__cross";
  cross.hidden = true;
  blueprint.append(cross);

  const dims = document.createElement("span");
  dims.className = "mswarm-dims";
  dims.style.setProperty("--mswarm-accent", accent);

  const caret = document.createElement("div");
  caret.className = "mswarm-caret";
  caret.style.setProperty("--mswarm-accent", accent);

  const guideH = document.createElement("div");
  guideH.className = "mswarm-guide mswarm-guide--h";
  guideH.style.setProperty("--mswarm-accent", accent);

  const guideV = document.createElement("div");
  guideV.className = "mswarm-guide mswarm-guide--v";
  guideV.style.setProperty("--mswarm-accent", accent);

  const spark = document.createElement("div");
  spark.className = "mswarm-spark";
  spark.style.setProperty("--mswarm-accent", accent);

  layer.append(guideH, guideV, blueprint, dims, caret, spark);

  return {
    blueprint,
    dims,
    cross,
    caret,
    guideH,
    guideV,
    spark,
    triggerSpark(x, y) {
      spark.style.setProperty("--sx", `${x.toFixed(1)}px`);
      spark.style.setProperty("--sy", `${y.toFixed(1)}px`);
      spark.classList.remove("is-firing");
      void spark.offsetWidth;
      spark.classList.add("is-firing");
    },
  };
}

/* ------------------------------------------------------------------ */
/* MascotSwarm Engine with Full 3D WebGL Shared Scene                 */
/* ------------------------------------------------------------------ */

export class MascotSwarm {
  constructor(scope, options = {}) {
    if (!scope) throw new Error("MascotSwarm: scope element required");
    this.scope = scope;
    this.opts = {
      bots: DEFAULT_BOTS.slice(0, 6),
      botCount: 6,
      botSize: 52,
      selector: null,
      mode: "scroll-trigger",
      origin: "gutters",
      originSelector: "[data-mascot]",
      dismissOnComplete: false,
      triggerOffset: 0.82,
      flightDurationMs: 440,
      baseDurationMs: 620,
      showTags: true,
      showPointers: true,
      showGuides: true,
      reversible: false,
      standby: "gutters",
      onBuild: null,
      onProgress: null,
      onComplete: null,
      ...options,
    };

    this.mounted = false;
    this.rafId = 0;
    this.lastFrameT = 0;
    this.completeFired = false;
    this.inViewport = true;
    this.manualReduced = false;
    this.scrubProgress = 0;
    this.pointer = { x: 0, y: 0, has: false };
    this._manualBuilding = false;
    this._emergeResolve = null;
    this.padX = 560;
    this.padY = 480;

    this.agents = [];
    this.targets = [];
    this.layer = null;
    this.canvas3D = null;
    this.renderer = null;
    this.scene = null;
    this.camera = null;
    this.envTex = null;

    this.reduceQuery = window.matchMedia("(prefers-reduced-motion: reduce)");

    this._tick = this._tick.bind(this);
    this._onScroll = this._onScroll.bind(this);
    this._onResize = this._onResize.bind(this);
    this._onPointerMove = this._onPointerMove.bind(this);
    this._onMotionChange = this._onMotionChange.bind(this);
  }

  isReducedMotion() {
    if (this.manualReduced) return true;
    if (this.reduceQuery.matches) return true;
    return document.documentElement.dataset.motion === "off";
  }

  mount() {
    if (this.mounted) return this;
    this.mounted = true;

    this.scope.classList.add("mswarm-scope");

    this.layer = document.createElement("div");
    this.layer.className = "mswarm-layer";
    this.layer.setAttribute("aria-hidden", "true");
    this.scope.appendChild(this.layer);

    /* Discover targets */
    const rawNodes = discoverTargets(this.scope, this.opts.selector);
    this.targets = rawNodes.map((el, i) => {
      const role = inferRole(el);
      return {
        id: `msw-t-${i}`,
        el,
        role,
        parentEl: el.parentElement?.closest("[data-swarm]") || null,
        parentTarget: null,
        rect: { x: 0, y: 0, w: 0, h: 0, radius: "12px" },
        state: "pending",
        assignedAgent: null,
        progress: 0,
      };
    });
    const byEl = new Map(this.targets.map((t) => [t.el, t]));
    this.targets.forEach((t) => {
      if (t.parentEl) t.parentTarget = byEl.get(t.parentEl) || null;
    });

    this.measure();

    /* Initialize Shared 3D WebGL Scene */
    const reduced = this.isReducedMotion();
    this.layer.hidden = reduced;

    this.canvas3D = document.createElement("canvas");
    this.canvas3D.className = "mswarm-canvas";
    this.canvas3D.style.left = `${-this.padX}px`;
    this.canvas3D.style.top = `${-this.padY}px`;
    this.canvas3D.style.width = `${this.stageRect.width + this.padX * 2}px`;
    this.canvas3D.style.height = `${this.stageRect.height + this.padY * 2}px`;
    this.layer.appendChild(this.canvas3D);

    try {
      this.renderer = new THREE.WebGLRenderer({
        canvas: this.canvas3D,
        alpha: true,
        antialias: true,
        powerPreference: "high-performance",
      });
      this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      this.renderer.setSize(this.stageRect.width + this.padX * 2, this.stageRect.height + this.padY * 2, false);
      this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
      this.renderer.toneMappingExposure = 1.0;
      this.renderer.outputColorSpace = THREE.SRGBColorSpace;

      this.scene = new THREE.Scene();
      this.envTex = getSharedPreviewContext().envMap || createStudioEnvMap(this.renderer);
      this.scene.environment = this.envTex;
      this.scene.environmentIntensity = 1.8;

      this.scene.add(new THREE.HemisphereLight(0xfff8f0, 0x362516, 3.2));
      const keyLight = new THREE.DirectionalLight(0xffffff, 2.4);
      keyLight.position.set(0, 200, 450);
      this.scene.add(keyLight);

      const rimLight = new THREE.DirectionalLight(0xffffff, 1.8);
      rimLight.position.set(300, -200, 350);
      this.scene.add(rimLight);

      const fillLight = new THREE.DirectionalLight(0xffffff, 0.9);
      fillLight.position.set(-300, -200, 250);
      this.scene.add(fillLight);

      /* Orthographic Camera mapped directly to CSS screen pixels with padding buffer */
      this.camera = new THREE.OrthographicCamera(
        -this.padX,
        this.stageRect.width + this.padX,
        this.padY,
        -(this.stageRect.height + this.padY),
        -1000,
        1000
      );
      this.camera.position.set(0, 0, 200);
    } catch (e) {
      console.warn("MascotSwarm: WebGL initialization failed", e);
    }

    this.targets.forEach((item) => {
      item.el.dataset.mswarmRole = item.role;
      item.state = reduced ? "built" : "pending";
      item.progress = reduced ? 1 : 0;
      item.el.dataset.mswarmState = item.state;
      item.el.style.setProperty("--mswarm-reveal", reduced ? "1" : "0");
    });

    /* Spawn 3D Mascot Agents */
    const cols = Math.max(this.opts.bots.length, 1);
    const isManual = this.opts.mode === "manual";
    const startScale = isManual ? 0.001 : 1;
    const startOpacity = isManual ? 0 : 1;

    this.agents = this.opts.bots.map((botDef, idx) => {
      /* Create 3D Rig in Three.js scene */
      let rig = null;
      if (this.scene) {
        rig = createBot3DRig(botDef);
        /* Scale unit radius 1.0 to bot size in pixels */
        const pixelRadius = this.opts.botSize * 0.44 * startScale;
        rig.rootGroup.scale.setScalar(pixelRadius);
        rig.rootGroup.visible = !isManual;
        this.scene.add(rig.rootGroup);
      }

      /* Lightweight DOM anchor carrying pointer and tag */
      const domAnchor = document.createElement("div");
      domAnchor.className = "mswarm-bot";
      domAnchor.style.setProperty("--bot-accent", botDef.accent);
      domAnchor.style.setProperty("--mswarm-bot-size", `${this.opts.botSize}px`);
      if (isManual) {
        domAnchor.style.opacity = "0";
      }

      if (this.opts.showPointers) {
        const pointerSvg = document.createElementNS(SVG_NS, "svg");
        pointerSvg.setAttribute("class", "mswarm-bot__pointer");
        pointerSvg.setAttribute("viewBox", "0 0 16 16");
        pointerSvg.setAttribute("fill", "none");
        const pPath = document.createElementNS(SVG_NS, "path");
        pPath.setAttribute("d", "M 2 2 L 13 6.5 L 7.8 8.3 L 6 13.5 Z");
        pPath.setAttribute("fill", botDef.accent);
        pPath.setAttribute("stroke", "#000000");
        pPath.setAttribute("stroke-width", "1.6");
        pPath.setAttribute("stroke-linejoin", "round");
        pointerSvg.appendChild(pPath);
        domAnchor.appendChild(pointerSvg);
      }

      if (this.opts.showTags && botDef.label) {
        const tag = document.createElement("span");
        tag.className = "mswarm-bot__tag";
        const dot = document.createElement("span");
        dot.className = "mswarm-bot__tag-dot";
        const txt = document.createElement("span");
        txt.textContent = botDef.label;
        tag.append(dot, txt);
        domAnchor.appendChild(tag);
      }

      this.layer.appendChild(domAnchor);
      const overlays = createAgentOverlays(this.layer, botDef.accent || "#e0a678");
      const restX = ((idx + 0.5) / cols) * Math.max(this.stageRect.width, 320);
      const restY = 48 + (idx % 2) * 36;

      if (rig) {
        rig.rootGroup.position.set(restX, -restY, isManual ? -55 : 0);
      }
      domAnchor.style.transform = `translate3d(${(restX - 26).toFixed(1)}px, ${(restY - 26).toFixed(1)}px, 0)`;

      return {
        idx,
        botDef,
        rig,
        domAnchor,
        overlays,
        x: restX,
        y: restY,
        z: isManual ? -55 : 0,
        scale: startScale,
        opacity: startOpacity,
        vx: 0,
        vy: 0,
        bankDeg: 0,
        homeX: restX,
        homeY: restY,
        phase: idx * 1.37,
        nextBlinkAt: 1.5 + Math.random() * 3.5,
        task: null,
        celebrateUntil: 0,
        lastActiveAt: 0,
      };
    });

    /* Observers and passive listeners */
    window.addEventListener("scroll", this._onScroll, { passive: true });
    window.addEventListener("resize", this._onResize, { passive: true });
    window.addEventListener("pointermove", this._onPointerMove, { passive: true });
    document.addEventListener("visibilitychange", this._onMotionChange);
    this.reduceQuery.addEventListener?.("change", this._onMotionChange);

    this.motionObserver = new MutationObserver(this._onMotionChange);
    this.motionObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["data-motion"],
    });

    this.resizeObserver = new ResizeObserver(this._onResize);
    this.resizeObserver.observe(this.scope);

    this.intersectionObserver = new IntersectionObserver(
      (entries) => {
        this.inViewport = entries[0]?.isIntersecting ?? true;
        this._syncLoop();
      },
      { threshold: 0, rootMargin: "160px 0px" }
    );
    this.intersectionObserver.observe(this.scope);

    if (!reduced) {
      this._evaluateScroll();
    }
    this._syncLoop();
    return this;
  }

  /** Batch-measure scope and every target in one read pass (zero layout thrash). */
  measure() {
    const sRect = this.scope.getBoundingClientRect();
    this.stageRect = {
      left: sRect.left,
      top: sRect.top,
      width: Math.max(sRect.width, 320),
      height: Math.max(sRect.height, 240),
    };

    const padLeft = typeof window !== "undefined" ? Math.max(sRect.left + 160, 560) : 560;
    const padRight = typeof window !== "undefined" ? Math.max(window.innerWidth - sRect.right + 160, 560) : 560;
    this.padX = Math.max(padLeft, padRight, 560);
    this.padY = typeof window !== "undefined" ? Math.max(window.innerHeight * 0.75, 480) : 480;

    if (this.canvas3D) {
      this.canvas3D.style.left = `${-this.padX}px`;
      this.canvas3D.style.top = `${-this.padY}px`;
      this.canvas3D.style.width = `${this.stageRect.width + this.padX * 2}px`;
      this.canvas3D.style.height = `${this.stageRect.height + this.padY * 2}px`;
    }

    if (this.renderer && this.camera && this.canvas3D) {
      this.renderer.setSize(this.stageRect.width + this.padX * 2, this.stageRect.height + this.padY * 2, false);
      this.camera.left = -this.padX;
      this.camera.right = this.stageRect.width + this.padX;
      this.camera.top = this.padY;
      this.camera.bottom = -(this.stageRect.height + this.padY);
      this.camera.updateProjectionMatrix();
    }

    const measurements = this.targets.map((item) => ({
      box: item.el.getBoundingClientRect(),
      radius: getComputedStyle(item.el).borderRadius || "12px",
    }));

    this.targets.forEach((item, i) => {
      const { box, radius } = measurements[i];
      item.rect = {
        x: box.left - sRect.left,
        y: box.top - sRect.top,
        w: box.width,
        h: box.height,
        radius: radius === "0px" ? "8px" : radius,
      };
    });
  }

  setReducedMotion(flag) {
    this.manualReduced = Boolean(flag);
    this._onMotionChange();
  }

  setMode(mode) {
    this.opts.mode = mode === "scroll-scrub" ? "scroll-scrub" : "scroll-trigger";
    this.replay();
  }

  setReversible(flag) {
    this.opts.reversible = Boolean(flag);
  }

  setBotCount(count) {
    const clamped = clamp(count, 1, DEFAULT_BOTS.length);
    this.opts.bots = DEFAULT_BOTS.slice(0, clamped);
    const wasMounted = this.mounted;
    if (wasMounted) {
      this.destroy();
      this.mount();
    }
  }

  setProgress(progress) {
    this.scrubProgress = clamp(progress, 0, 1);
    if (!this.mounted || this.isReducedMotion()) return;
    this._applyScrubProgress(this.scrubProgress);
  }

  _getMascotOrigin() {
    const sRect = this.scope.getBoundingClientRect();
    const mascotEl = document.querySelector(this.opts.originSelector || "[data-mascot]");
    if (mascotEl) {
      const mRect = mascotEl.getBoundingClientRect();
      const isVisibleOnScreen =
        mRect.width > 0 &&
        mRect.height > 0 &&
        mRect.bottom > 40 &&
        mRect.top < window.innerHeight - 20;
      if (isVisibleOnScreen) {
        return {
          x: mRect.left + mRect.width * 0.5 - sRect.left,
          y: mRect.top + mRect.height * 0.5 - sRect.top,
        };
      }
    }
    const isDesktop = typeof window !== "undefined" && window.innerWidth >= 900;
    const fallbackScreenX = isDesktop
      ? Math.max(48, Math.min(window.innerWidth * 0.08, 96))
      : (typeof window !== "undefined" ? window.innerWidth * 0.5 : 96);
    const fallbackScreenY = typeof window !== "undefined"
      ? (isDesktop ? window.innerHeight - 90 : window.innerHeight - 60)
      : 600;
    return {
      x: fallbackScreenX - sRect.left,
      y: fallbackScreenY - sRect.top,
    };
  }

  emergeAndBuild(options = {}) {
    if (!this.mounted) this.mount();
    if (this.isReducedMotion()) {
      this.completeAll();
      this.scope.classList.remove("mswarm-section--empty");
      return Promise.resolve();
    }

    this.scope.classList.remove("mswarm-section--empty");
    this.inViewport = true;
    this._manualBuilding = true;
    this.measure();
    this.completeFired = false;

    const origin = this._getMascotOrigin();
    const facingRight = origin.x < this.stageRect.width * 0.5;
    const angles = facingRight
      ? [-0.85, -0.48, -0.08, 0.28, 0.64, 1.05]
      : [Math.PI - 1.05, Math.PI - 0.64, Math.PI - 0.28, Math.PI + 0.08, Math.PI + 0.48, Math.PI + 0.85];

    this.targets.forEach((item) => {
      item.assignedAgent = null;
      item.state = "pending";
      item.progress = 0;
      item.el.dataset.mswarmState = "pending";
      item.el.style.setProperty("--mswarm-reveal", "0");
    });

    this.agents.forEach((ag, idx) => {
      ag.task = null;
      ag.celebrateUntil = 0;
      ag.x = origin.x;
      ag.y = origin.y;
      ag.z = -65;
      ag.scale = 0.001;
      ag.opacity = 0;
      if (ag.rig) {
        ag.rig.rootGroup.visible = true;
        ag.rig.rootGroup.position.set(ag.x, -ag.y, ag.z);
        ag.rig.rootGroup.scale.setScalar(0.001);
        ag.rig.setMood("working");
      }
      if (ag.domAnchor) {
        ag.domAnchor.style.opacity = "0";
        ag.domAnchor.style.transform = `translate3d(${(ag.x - 26).toFixed(1)}px, ${(ag.y - 26).toFixed(1)}px, 0)`;
      }

      const theta = angles[idx % angles.length];
      const burstDist = 95 + (idx % 3) * 38;
      const relBurstX = Math.cos(theta) * burstDist;
      const relBurstY = Math.sin(theta) * burstDist;

      ag.task = {
        kind: "emerge",
        t: 0,
        delay: idx * 0.085,
        dur: 0.58,
        relBurstX,
        relBurstY,
      };
    });

    this._syncLoop();

    return new Promise((resolve) => {
      this._emergeResolve = resolve;
    });
  }

  replay() {
    if (!this.mounted) return;
    this.completeFired = false;
    this.measure();
    const reduced = this.isReducedMotion();

    this.agents.forEach((ag, idx) => {
      ag.task = null;
      ag.celebrateUntil = 0;
      ag.rig?.setMood("idle");
      this._hideAgentOverlays(ag);
      if (!reduced) {
        const side = idx % 2 === 0 ? -40 : this.stageRect.width + 40;
        ag.x = side;
        ag.y = Math.max(24, window.scrollY - (this.stageRect.top + window.scrollY) + 60 + idx * 44);
        ag.z = 0;
      }
    });

    this.targets.forEach((item) => {
      item.assignedAgent = null;
      item.state = reduced ? "built" : "pending";
      item.progress = reduced ? 1 : 0;
      item.el.dataset.mswarmState = item.state;
      item.el.style.setProperty("--mswarm-reveal", reduced ? "1" : "0");
    });

    if (!reduced) {
      this._evaluateScroll();
    }
    this._syncLoop();
  }

  completeAll() {
    this.targets.forEach((item) => {
      item.assignedAgent = null;
      item.state = "built";
      item.progress = 1;
      item.el.dataset.mswarmState = "built";
      item.el.style.setProperty("--mswarm-reveal", "1");
    });
    this.agents.forEach((ag) => {
      ag.task = null;
      ag.rig?.setMood("idle");
      this._hideAgentOverlays(ag);
    });
  }

  destroy() {
    if (!this.mounted) return;
    this.mounted = false;
    cancelAnimationFrame(this.rafId);
    this.rafId = 0;

    window.removeEventListener("scroll", this._onScroll);
    window.removeEventListener("resize", this._onResize);
    window.removeEventListener("pointermove", this._onPointerMove);
    document.removeEventListener("visibilitychange", this._onMotionChange);
    this.reduceQuery.removeEventListener?.("change", this._onMotionChange);
    this.motionObserver?.disconnect();
    this.resizeObserver?.disconnect();
    this.intersectionObserver?.disconnect();

    this.agents.forEach((ag) => {
      ag.rig?.destroy();
      ag.domAnchor?.remove();
    });
    this.agents = [];

    this.targets.forEach((item) => {
      item.el.removeAttribute("data-mswarm-state");
      item.el.removeAttribute("data-mswarm-role");
      item.el.style.removeProperty("--mswarm-reveal");
    });
    this.targets = [];

    this.envTex?.dispose();
    this.renderer?.dispose();
    this.canvas3D?.remove();
    this.layer?.remove();
    this.layer = null;
    this.scope.classList.remove("mswarm-scope");
  }

  _onMotionChange() {
    const reduced = this.isReducedMotion();
    if (this.layer) this.layer.hidden = reduced;
    if (reduced) {
      this.completeAll();
    }
    this._syncLoop();
  }

  _onResize() {
    if (!this.mounted) return;
    this.measure();
    if (!this.isReducedMotion()) {
      this._evaluateScroll();
    }
  }

  _onPointerMove(e) {
    const sRect = this.scope.getBoundingClientRect();
    this.pointer = {
      x: e.clientX - sRect.left,
      y: e.clientY - sRect.top,
      has: true,
    };
  }

  _onScroll() {
    if (!this.mounted || this.isReducedMotion()) return;
    this._evaluateScroll();
    this._syncLoop();
  }

  _visibleScopeBand() {
    const rect = this.scope.getBoundingClientRect();
    const topInScope = clamp(-rect.top, 0, rect.height);
    const triggerY = clamp(window.innerHeight * this.opts.triggerOffset - rect.top, 0, rect.height + 120);
    return { rect, topInScope, triggerY };
  }

  _evaluateScroll() {
    if (this.opts.mode === "scroll-scrub") {
      const rect = this.scope.getBoundingClientRect();
      const startY = window.innerHeight * 0.78;
      const travel = Math.max(rect.height - window.innerHeight * 0.25, 220);
      const raw = (startY - rect.top) / travel;
      this._applyScrubProgress(clamp(raw, 0, 1));
      return;
    }

    const { triggerY } = this._visibleScopeBand();

    if (this.opts.reversible) {
      for (const item of this.targets) {
        if (item.rect.y > triggerY + 90 && item.state !== "pending") {
          if (item.assignedAgent && item.assignedAgent.task?.item === item) {
            this._hideAgentOverlays(item.assignedAgent);
            item.assignedAgent.task = null;
          }
          item.assignedAgent = null;
          item.state = "pending";
          item.progress = 0;
          item.el.dataset.mswarmState = "pending";
          item.el.style.setProperty("--mswarm-reveal", "0");
          this.completeFired = false;
        }
      }
    }

    this._assignTasks(triggerY);
  }

  _applyScrubProgress(p) {
    const n = this.targets.length;
    if (!n) return;
    const overlap = 0.65;
    const totalSpan = n + overlap;
    const cursor = p * totalSpan;

    this.targets.forEach((item, i) => {
      const localP = clamp(cursor - i, 0, 1);
      item.progress = localP;
      if (localP <= 0) {
        item.state = "pending";
        item.el.dataset.mswarmState = "pending";
        item.el.style.setProperty("--mswarm-reveal", "0");
      } else if (localP < 1) {
        item.state = "building";
        item.el.dataset.mswarmState = "building";
        item.el.style.setProperty("--mswarm-reveal", easeOutCubic(localP).toFixed(3));
      } else {
        item.state = "built";
        item.el.dataset.mswarmState = "built";
        item.el.style.setProperty("--mswarm-reveal", "1");
      }
    });

    const activeIndices = this.targets
      .map((item, idx) => ({ item, idx, localP: item.progress }))
      .filter((d) => d.localP > 0 && d.localP < 1)
      .slice(0, this.agents.length);

    this.agents.forEach((ag, agIdx) => {
      const match = activeIndices[agIdx];
      if (match) {
        const pt = this._buildPointForRole(match.item, match.localP);
        ag.task = { kind: "scrub", targetX: pt.x, targetY: pt.y, item: match.item };
        if (Math.abs(ag.x) > this.stageRect.width || ag.x <= 0) {
          ag.x = pt.x;
          ag.y = pt.y;
        }
        this._renderOverlaysForProgress(ag, match.item, match.localP, pt);
      } else {
        if (ag.task?.kind === "scrub") ag.task = null;
        this._hideAgentOverlays(ag);
      }
    });
    this.opts.onProgress?.(p);
  }

  _assignTasks(triggerY) {
    const isManualBuild = this._manualBuilding;
    if (this.opts.mode === "manual" && !this._manualBuilding) return;

    const ready = this.targets.filter(
      (item) =>
        item.state === "pending" &&
        (isManualBuild || item.rect.y <= triggerY) &&
        (!item.parentTarget || item.parentTarget.state === "built" || item.parentTarget.progress >= 0.25)
    );
    if (!ready.length) return;

    const idleAgents = this.agents.filter((ag) => !ag.task);
    for (const ag of idleAgents) {
      if (!ready.length) break;
      let pickIdx = ready.findIndex((item) => item.role === ag.botDef.role);
      if (pickIdx === -1) pickIdx = 0;
      const [item] = ready.splice(pickIdx, 1);
      this._startTask(ag, item, ready.length);
    }
  }

  _startTask(ag, item, backlog) {
    item.state = "building";
    item.assignedAgent = ag;
    item.progress = 0;
    item.el.dataset.mswarmState = "building";
    item.el.style.setProperty("--mswarm-reveal", "0");

    const speedBoost = clamp(1 + backlog * 0.25, 1, 3.0);
    const startPt = this._buildPointForRole(item, 0);

    if (Math.abs(ag.y - startPt.y) > window.innerHeight * 0.85) {
      ag.x = ag.idx % 2 === 0 ? -36 : this.stageRect.width + 36;
      ag.y = startPt.y - 40;
    }

    const dx = startPt.x - ag.x;
    const dy = startPt.y - ag.y;
    const arcLift = Math.min(90, Math.hypot(dx, dy) * 0.28);

    ag.task = {
      kind: "build",
      item,
      phase: "fly",
      t: 0,
      flyDur: (this.opts.flightDurationMs / 1000) / speedBoost,
      workDur: (this.opts.baseDurationMs / 1000) / speedBoost,
      fromX: ag.x,
      fromY: ag.y,
      c1X: lerp(ag.x, startPt.x, 0.35),
      c1Y: lerp(ag.y, startPt.y, 0.25) - arcLift,
      c2X: lerp(ag.x, startPt.x, 0.72),
      c2Y: lerp(ag.y, startPt.y, 0.8) - arcLift * 0.4,
      toX: startPt.x,
      toY: startPt.y,
    };
  }

  _buildPointForRole(item, p) {
    const r = item.rect;
    switch (item.role) {
      case "heading":
      case "text":
        return {
          x: r.x + r.w * easeInOutCubic(p),
          y: r.y + Math.min(r.h * 0.55, 22),
        };
      case "control":
        return {
          x: r.x + r.w * lerp(0.15, 0.85, p),
          y: r.y + r.h * 0.5,
        };
      case "media":
        return {
          x: r.x + r.w * lerp(0.08, 0.96, p),
          y: r.y + r.h * lerp(0.08, 0.92, p),
        };
      case "box":
      default: {
        if (p < 0.4) {
          const k = p / 0.4;
          return { x: r.x + r.w * k, y: r.y };
        }
        const k = (p - 0.4) / 0.6;
        return { x: r.x + r.w, y: r.y + r.h * k };
      }
    }
  }

  _renderOverlaysForProgress(ag, item, p, pt) {
    const { blueprint, dims, cross, caret, guideH, guideV } = ag.overlays;
    const r = item.rect;

    if (this.opts.showGuides) {
      guideH.style.transform = `translate3d(0, ${pt.y.toFixed(1)}px, 0)`;
      guideV.style.transform = `translate3d(${pt.x.toFixed(1)}px, 0, 0)`;
      guideH.classList.add("is-active");
      guideV.classList.add("is-active");
    }

    if (item.role === "box" || item.role === "media" || item.role === "control") {
      let sx = 1;
      let sy = 1;
      if (item.role === "box") {
        if (p < 0.4) {
          sx = clamp(p / 0.4, 0.08, 1);
          sy = 0.14;
        } else {
          sx = 1;
          sy = clamp(0.14 + ((p - 0.4) / 0.6) * 0.86, 0.14, 1);
        }
      } else if (item.role === "media") {
        const ep = easeInOutCubic(p);
        sx = clamp(0.12 + ep * 0.88, 0.12, 1);
        sy = clamp(0.12 + ep * 0.88, 0.12, 1);
      } else {
        const ep = easeOutCubic(p);
        sx = clamp(0.2 + ep * 0.8, 0.2, 1);
        sy = 1;
      }
      const curW = Math.max(8, r.w * sx);
      const curH = Math.max(8, r.h * sy);
      if (ag._lastBoxItem !== item) {
        ag._lastBoxItem = item;
        blueprint.style.width = `${r.w.toFixed(1)}px`;
        blueprint.style.height = `${r.h.toFixed(1)}px`;
        blueprint.style.setProperty("--mswarm-radius", r.radius);
      }
      blueprint.style.transform = `translate3d(${r.x.toFixed(1)}px, ${r.y.toFixed(1)}px, 0) scale(${sx.toFixed(3)}, ${sy.toFixed(3)})`;
      dims.textContent = `${Math.round(curW)} × ${Math.round(curH)}`;
      dims.style.transform = `translate3d(${r.x.toFixed(1)}px, ${(r.y - 22).toFixed(1)}px, 0)`;
      dims.classList.add("is-active");
      cross.hidden = item.role !== "media";
      blueprint.classList.add("is-active");
      blueprint.classList.toggle("is-snapped", p > 0.9);
      caret.classList.remove("is-active");
    } else {
      blueprint.classList.remove("is-active");
      dims.classList.remove("is-active");
      const caretH = Math.min(Math.max(r.h * 0.72, 16), 34);
      caret.style.height = `${caretH.toFixed(1)}px`;
      caret.style.transform = `translate3d(${pt.x.toFixed(1)}px, ${r.y.toFixed(1)}px, 0)`;
      caret.classList.add("is-active");
    }
  }

  _hideAgentOverlays(ag) {
    const { blueprint, dims, caret, guideH, guideV } = ag.overlays;
    blueprint.classList.remove("is-active", "is-snapped");
    dims.classList.remove("is-active");
    caret.classList.remove("is-active");
    guideH.classList.remove("is-active");
    guideV.classList.remove("is-active");
  }

  _syncLoop() {
    if (!this.mounted || this.isReducedMotion() || document.hidden) {
      cancelAnimationFrame(this.rafId);
      this.rafId = 0;
      return;
    }
    if (!this._manualBuilding && !this.inViewport) {
      cancelAnimationFrame(this.rafId);
      this.rafId = 0;
      return;
    }
    if (this.opts.dismissOnComplete && this.completeFired) {
      const allDismissed = this.agents.every((ag) => !ag.task && (ag.scale === undefined || ag.scale <= 0.02));
      if (allDismissed) {
        cancelAnimationFrame(this.rafId);
        this.rafId = 0;
        return;
      }
    }
    if (!this.rafId) {
      this.lastFrameT = performance.now();
      this.rafId = requestAnimationFrame(this._tick);
    }
  }

  _tick(now) {
    if (!this.mounted || this.isReducedMotion() || document.hidden) {
      this.rafId = 0;
      return;
    }
    if (!this._manualBuilding && !this.inViewport) {
      this.rafId = 0;
      return;
    }
    const dt = Math.min((now - this.lastFrameT) / 1000, 0.05);
    this.lastFrameT = now;
    const tSec = now / 1000;

    const { topInScope, triggerY } = this._visibleScopeBand();

    if (this.opts.mode === "scroll-trigger" || this._manualBuilding) {
      this._assignTasks(triggerY);
    }

    for (const ag of this.agents) {
      if (tSec >= ag.nextBlinkAt) {
        ag.nextBlinkAt = tSec + 2.2 + Math.random() * 3.8;
        ag.rig?.blink();
      }

      const prevX = ag.x;
      const prevY = ag.y;

      if (ag.task && ag.task.kind === "emerge") {
        const task = ag.task;
        if (task.delay > 0) {
          task.delay -= dt;
          ag.scale = 0.001;
          ag.opacity = 0;
        } else {
          task.t += dt / task.dur;
          const p = Math.min(task.t, 1);
          const ep = 1 - Math.pow(1 - p, 4);

          const liveOrigin = this._getMascotOrigin();
          const targetBurstX = liveOrigin.x + task.relBurstX;
          const targetBurstY = liveOrigin.y + task.relBurstY;

          ag.x = lerp(liveOrigin.x, targetBurstX, ep);
          ag.y = lerp(liveOrigin.y, targetBurstY, ep);
          ag.z = lerp(-65, 10, ep) + Math.sin(p * Math.PI) * 32;
          ag.scale = lerp(0.01, 1.0, ep);
          ag.opacity = lerp(0, 1.0, Math.min(p * 2.2, 1));

          if (task.t >= 1) {
            ag.task = null;
            ag.z = 10;
            ag.scale = 1.0;
            ag.opacity = 1.0;
            ag.overlays?.triggerSpark(ag.x, ag.y);
          }
        }
      } else if (ag.task && ag.task.kind === "return") {
        const task = ag.task;
        if (task.delay > 0) {
          task.delay -= dt;
        } else {
          task.t += dt / task.dur;
          const p = Math.min(task.t, 1);
          const ep = easeInOutCubic(p);

          const liveOrigin = this._getMascotOrigin();
          ag.x = lerp(task.fromX, liveOrigin.x, ep);
          ag.y = lerp(task.fromY, liveOrigin.y, ep);
          ag.z = lerp(10, -65, ep) + Math.sin(p * Math.PI) * 18;
          ag.scale = lerp(1.0, 0.01, ep);
          ag.opacity = lerp(1.0, 0, Math.max(0, (p - 0.45) / 0.55));

          if (task.t >= 1) {
            ag.task = null;
            ag.scale = 0.001;
            ag.opacity = 0;
            if (ag.rig) ag.rig.rootGroup.visible = false;
            if (ag.domAnchor) ag.domAnchor.style.opacity = "0";
          }
        }
      } else if (ag.task && ag.task.kind === "build") {
        const task = ag.task;
        const item = task.item;

        if (task.phase === "fly") {
          task.t += dt / Math.max(task.flyDur, 0.08);
          const p = easeInOutCubic(Math.min(task.t, 1));
          ag.x = cubicPoint(task.fromX, task.c1X, task.c2X, task.toX, p);
          ag.y = cubicPoint(task.fromY, task.c1Y, task.c2Y, task.toY, p);
          ag.z = Math.sin(p * Math.PI) * 55; // 3D flight altitude arc
          ag.rig?.setMood("idle");

          if (task.t >= 1) {
            task.phase = "work";
            task.t = 0;
            ag.rig?.setMood("working");
          }
        } else {
          task.t += dt / Math.max(task.workDur, 0.08);
          const p = Math.min(task.t, 1);
          const pt = this._buildPointForRole(item, p);
          const follow = 1 - Math.exp(-22 * dt);
          ag.x += (pt.x - ag.x) * follow;
          ag.y += (pt.y - ag.y) * follow;
          ag.z = 10;

          item.progress = p;
          item.el.style.setProperty("--mswarm-reveal", easeOutCubic(p).toFixed(3));
          this._renderOverlaysForProgress(ag, item, p, pt);

          if (p >= 1) {
            item.state = "built";
            item.assignedAgent = null;
            item.el.dataset.mswarmState = "built";
            item.el.style.setProperty("--mswarm-reveal", "1");
            ag.overlays.triggerSpark(pt.x, pt.y);
            this._hideAgentOverlays(ag);
            ag.task = null;
            ag.lastActiveAt = tSec;
            ag.celebrateUntil = tSec + 0.38;
            ag.rig?.setMood("celebrating");
            this.opts.onBuild?.(item.el, ag.botDef);
          }
        }
      } else if (ag.task && ag.task.kind === "scrub") {
        const follow = 1 - Math.exp(-16 * dt);
        ag.x += (ag.task.targetX - ag.x) * follow;
        ag.y += (ag.task.targetY - ag.y) * follow;
        ag.z = 15;
        ag.lastActiveAt = tSec;
        ag.rig?.setMood("working");
      } else {
        if (this.opts.mode === "manual" && !this._manualBuilding) {
          ag.scale = 0.001;
          ag.opacity = 0;
        } else {
          if (tSec > ag.celebrateUntil) {
            ag.rig?.setMood("idle");
          }
          const bandTop = clamp(topInScope + 40, 24, Math.max(24, this.stageRect.height - 200));
          const bandSpan = Math.max(120, Math.min(340, triggerY - topInScope));
          const onRight = ag.idx % 2 === 1;
          const rowSlot = Math.floor(ag.idx / 2) / Math.max(1, Math.ceil(this.agents.length / 2));
          const hasGutter = this.stageRect.width >= 720 && window.innerWidth - this.stageRect.width >= 140;
          const edgeX = onRight
            ? (hasGutter ? this.stageRect.width + 12 : this.stageRect.width - 54)
            : (hasGutter ? -64 : 6);
          const idleTargetX = edgeX + Math.sin(tSec * 0.85 + ag.phase) * 8;
          const idleTargetY = bandTop + rowSlot * bandSpan + Math.cos(tSec * 1.1 + ag.phase * 1.3) * 14;

          const follow = 1 - Math.exp(-3.4 * dt);
          ag.x += (idleTargetX - ag.x) * follow;
          ag.y += (idleTargetY - ag.y) * follow;
          ag.z = 0;
        }
      }

      const instVx = dt > 1e-4 ? (ag.x - prevX) / dt : 0;
      const instVy = dt > 1e-4 ? (ag.y - prevY) / dt : 0;
      ag.vx += (instVx - ag.vx) * (1 - Math.exp(-10 * dt));
      ag.vy += (instVy - ag.vy) * (1 - Math.exp(-10 * dt));

      const isWorking = ag.task && (ag.task.phase === "work" || ag.task.kind === "scrub");
      const targetBank = isWorking ? 0 : clamp(ag.vx * 0.022, -18, 18);
      ag.bankDeg += (targetBank - ag.bankDeg) * (1 - Math.exp(-12 * dt));

      /* Update 3D Bot Transforms */
      if (ag.rig) {
        const curScale = (ag.scale !== undefined ? ag.scale : 1);
        ag.rig.rootGroup.visible = curScale > 0.02;
        const pixelRadius = this.opts.botSize * 0.44 * curScale;
        ag.rig.rootGroup.scale.setScalar(Math.max(0.001, pixelRadius));

        const bobY = isWorking ? 0 : Math.sin(tSec * 2.4 + ag.phase) * 3.5;
        ag.rig.rootGroup.position.set(ag.x, -(ag.y + bobY), ag.z || 0);
        ag.rig.rootGroup.rotation.z = (-ag.bankDeg * Math.PI) / 180;
        ag.rig.rootGroup.rotation.x = clamp(ag.vy * 0.0016, -0.25, 0.25);

        if (Math.hypot(ag.vx, ag.vy) > 45) {
          ag.rig.setGaze(clamp(ag.vx / 420, -1, 1), clamp(ag.vy / 420, -1, 1));
        } else if (this.pointer.has) {
          ag.rig.setGaze(
            clamp((this.pointer.x - ag.x) / 360, -1, 1),
            clamp((this.pointer.y - ag.y) / 280, -1, 1)
          );
        } else {
          ag.rig.setGaze(
            Math.sin(tSec * 0.8 + ag.phase) * 0.45,
            Math.cos(tSec * 0.6 + ag.phase) * 0.25
          );
        }
      }

      /* Update DOM pointer tip and Figma role tag anchors */
      if (ag.domAnchor) {
        const domScale = (ag.scale !== undefined ? ag.scale : 1);
        ag.domAnchor.style.transform = `translate3d(${(ag.x - 26).toFixed(1)}px, ${(ag.y - 26).toFixed(1)}px, 0) scale(${domScale.toFixed(3)})`;
        ag.domAnchor.style.opacity = ag.opacity !== undefined ? String(ag.opacity) : "1";
        ag.domAnchor.classList.toggle("is-working", isWorking);
        ag.domAnchor.classList.toggle("is-celebrating", tSec <= ag.celebrateUntil);
      }
    }

    /* Render the shared 3D WebGL scene */
    if (this.renderer && this.scene && this.camera) {
      this.renderer.render(this.scene, this.camera);
    }

    if (!this.completeFired && this.targets.length && this.targets.every((t) => t.state === "built")) {
      this.completeFired = true;
      this.opts.onComplete?.();
      if (this._emergeResolve) {
        this._emergeResolve();
        this._emergeResolve = null;
      }

      if (this.opts.dismissOnComplete) {
        window.setTimeout(() => {
          if (!this.mounted) return;
          this.agents.forEach((ag, idx) => {
            ag.task = {
              kind: "return",
              t: 0,
              delay: idx * 0.075,
              dur: 0.68,
              fromX: ag.x,
              fromY: ag.y,
            };
            ag.rig?.setMood("idle");
          });
          this._syncLoop();
        }, 1200);
      }
    }

    if (this.opts.dismissOnComplete && this.completeFired) {
      const allDismissed = this.agents.every((ag) => !ag.task && (ag.scale === undefined || ag.scale <= 0.02));
      if (allDismissed) {
        this.rafId = 0;
        return;
      }
    }

    this.rafId = requestAnimationFrame(this._tick);
  }
}

/* ------------------------------------------------------------------ */
/* Original Mascot Speech & Section Auto-Builder Integration          */
/* ------------------------------------------------------------------ */

export async function speakMascot(text, duration = 4800) {
  if (typeof window === "undefined" || !text) return;
  if (typeof mascotCheer === "function") {
    mascotCheer("happy");
  } else if (typeof window.__mascotCheer === "function") {
    window.__mascotCheer("happy");
  }

  if (!registry.mascotSpeech && registry.loaders?.mascotSpeech) {
    try {
      await registry.loaders.mascotSpeech();
    } catch (_) {}
  }

  if (registry.mascotSpeech && typeof registry.mascotSpeech.say === "function") {
    registry.mascotSpeech.say(text, duration);
    return;
  }

  const textEl = document.getElementById("mascot-speech-text");
  const speechEl = document.getElementById("mascot-speech");
  if (textEl && speechEl) {
    textEl.textContent = text;
    speechEl.classList.remove("is-switching");
  }
}

export function initMascotSwarmSections() {
  if (typeof document === "undefined") return null;

  const section2 = document.getElementById("systems");
  const section3 = document.getElementById("console");
  if (!section2 || !section3) return null;

  const swarms = new Map();

  const swarm2 = new MascotSwarm(section2, {
    selector: "[data-swarm]",
    origin: "mascot",
    originSelector: "[data-mascot]",
    mode: "manual",
    dismissOnComplete: true,
    botCount: 6,
    botSize: 52,
  }).mount();
  swarms.set("systems", swarm2);

  const swarm3 = new MascotSwarm(section3, {
    selector: "[data-swarm]",
    origin: "mascot",
    originSelector: "[data-mascot]",
    mode: "manual",
    dismissOnComplete: true,
    botCount: 6,
    botSize: 52,
  }).mount();
  swarms.set("console", swarm3);

  let section2Building = false;
  let section2Done = false;
  let section3Triggered = false;

  const triggerSection3 = () => {
    if (!section2Done || section3Triggered) return;
    section3Triggered = true;
    speakMascot("Ohh I guess this section was left empty... let me build it!", 4800);
    swarm3.emergeAndBuild();
  };

  const checkSection3 = () => {
    if (!section2Done || section3Triggered) return;
    const r = section3.getBoundingClientRect();
    if (r.top < window.innerHeight * 0.75 && r.bottom > 120) {
      triggerSection3();
    }
  };

  const triggerSection2 = () => {
    if (section2Building || section2Done) return;
    section2Building = true;
    speakMascot("Ohh I guess this section was left empty... let me build it!", 4800);
    swarm2.emergeAndBuild().then(() => {
      section2Building = false;
      section2Done = true;
      window.setTimeout(() => {
        checkSection3();
      }, 1200);
    });
  };

  const obs2 = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting && !section2Building && !section2Done) {
          obs2.disconnect();
          triggerSection2();
        }
      }
    },
    { threshold: 0.05, rootMargin: "0px 0px -40px 0px" }
  );
  obs2.observe(section2);

  const obs3 = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) {
          if (section2Done) {
            obs3.disconnect();
            triggerSection3();
          }
        }
      }
    },
    { threshold: 0.2, rootMargin: "0px 0px -40px 0px" }
  );
  obs3.observe(section3);

  window.addEventListener(
    "scroll",
    () => {
      if (section2Done && !section3Triggered) {
        checkSection3();
      }
    },
    { passive: true }
  );

  return swarms;
}
